-- ----------------------------------------------------------------------------
-- RESET: drop our objects first so this file is safely re-runnable. Safe while
-- there is no real data yet; remove this block once players have signed up.
-- ----------------------------------------------------------------------------
drop trigger if exists on_auth_user_created on auth.users;
drop table if exists public.predictions cascade;
drop table if exists public.league_members cascade;
drop table if exists public.leagues cascade;
drop table if exists public.fixtures cascade;
drop table if exists public.players cascade;
drop table if exists public.gameweeks cascade;
drop table if exists public.profiles cascade;
drop table if exists public.teams cascade;
drop view if exists public.leaderboard cascade;
drop type if exists public.gameweek_status cascade;
drop type if exists public.fixture_status cascade;
drop function if exists public.handle_new_user() cascade;
drop function if exists public.match_outcome(int, int) cascade;
drop function if exists public.settle_fixture(text) cascade;
drop function if exists public.unsettle_fixture(text) cascade;
drop function if exists public.league_leaderboard(uuid) cascade;
drop function if exists public.is_admin() cascade;
drop function if exists public.fixture_deadline_passed(text) cascade;
drop function if exists public.fixture_deadline_passed(uuid) cascade;
drop function if exists public.is_league_member(uuid, uuid) cascade;
drop function if exists public.create_league(text) cascade;
drop function if exists public.join_league_by_code(text) cascade;

-- ============================================================
-- supabase/migrations/0001_schema.sql
-- ============================================================
-- ============================================================================
-- Real Predictions — Core Schema
-- ============================================================================
-- A Premier League prediction game. Players predict 5 fixtures per gameweek
-- and earn points:
--   * Exact score        -> 3 points
--   * Correct outcome    -> 1 point  (win/draw/loss direction, not exact)
--   * Correct POTM       -> 2 points (Player of the Match)
-- Exact score supersedes the outcome point (you get 3, not 3+1).
-- POTM is independent (+2 on top). Max per fixture = 5, per gameweek = 25.
-- ============================================================================

-- Enable UUID generation
create extension if not exists "pgcrypto";

-- ----------------------------------------------------------------------------
-- profiles: one row per user, linked to Supabase's built-in auth.users table.
-- Supabase handles passwords/Google login in auth.users; this holds the
-- game-specific profile info we collect during onboarding.
-- ----------------------------------------------------------------------------
create table public.profiles (
  id                uuid primary key references auth.users(id) on delete cascade,
  display_name      text not null,
  -- FK to teams is added after the teams table is created (see below).
  favourite_team_id text,
  avatar_url        text,
  avatar_emoji      text,                     -- simple emoji avatar chosen at onboarding
  is_admin          boolean not null default false,
  onboarded         boolean not null default false,  -- finished profile setup (name/team/avatar)
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);

-- ----------------------------------------------------------------------------
-- teams: the Premier League clubs. Synced from football-data.org so the roster
-- always matches the current season (promotions/relegations handled by the API).
-- external_id maps a row to that API's team id.
-- ----------------------------------------------------------------------------
create table public.teams (
  id          text primary key,            -- stable slug, e.g. "ars" (matches the app's ids)
  external_id integer unique,              -- football-data.org / FPL team id
  name        text not null,               -- e.g. "Arsenal FC"
  short_name  text not null,               -- e.g. "Arsenal"
  tla         text,                        -- three-letter abbr, e.g. "ARS"
  color       text,                        -- brand colour (badge fallback / accents)
  crest_url   text,                         -- club badge image
  created_at  timestamptz not null default now()
);

-- profiles.favourite_team_id references teams, but teams is created after
-- profiles above; add the FK now that teams exists.
alter table public.profiles
  add constraint profiles_favourite_team_fk
  foreign key (favourite_team_id) references public.teams(id) on delete set null;

-- ----------------------------------------------------------------------------
-- players: squad members, used for Player of the Match predictions. Both the
-- user's prediction and the actual POTM reference a player_id, so scoring is an
-- exact id match (no fragile "Saka" vs "Bukayo Saka" string comparison).
-- Synced from football-data.org squads.
-- ----------------------------------------------------------------------------
create table public.players (
  id          text primary key,            -- stable slug, e.g. "p452"
  external_id integer unique,              -- football-data.org / FPL player id
  team_id     text not null references public.teams(id) on delete cascade,
  name        text not null,
  position    text,
  created_at  timestamptz not null default now()
);

-- ----------------------------------------------------------------------------
-- gameweeks: a round of exactly 5 fixtures the admin selects one week ahead.
-- deadline is when predictions lock (typically first kickoff of the round).
-- ----------------------------------------------------------------------------
create type gameweek_status as enum ('draft', 'open', 'locked', 'completed');

create table public.gameweeks (
  id          text primary key,            -- stable slug, e.g. "gw1"
  number      integer not null unique,     -- Gameweek 1, 2, 3...
  title       text,                        -- optional label, e.g. "Opening Weekend"
  deadline    timestamptz not null,        -- predictions lock at this time
  status      gameweek_status not null default 'draft',
  created_at  timestamptz not null default now()
);

-- ----------------------------------------------------------------------------
-- fixtures: the individual matches inside a gameweek (5 per gameweek).
-- Scores auto-fill from football-data.org; POTM is entered manually by admin.
-- ----------------------------------------------------------------------------
create type fixture_status as enum ('scheduled', 'in_play', 'finished');

create table public.fixtures (
  id            text primary key,          -- stable slug, e.g. "f1"
  external_id   integer unique,            -- football-data.org / FPL match id
  gameweek_id   text not null references public.gameweeks(id) on delete cascade,
  home_team_id  text not null references public.teams(id),
  away_team_id  text not null references public.teams(id),
  kickoff_time  timestamptz not null,
  status        fixture_status not null default 'scheduled',
  home_score    integer,                   -- null until the match finishes
  away_score    integer,
  potm_player_id text references public.players(id),  -- manual, null until entered
  result_settled_at timestamptz,           -- set when scores+POTM finalize scoring
  created_at    timestamptz not null default now(),
  constraint different_teams check (home_team_id <> away_team_id)
);

create index fixtures_gameweek_idx on public.fixtures(gameweek_id);

-- ----------------------------------------------------------------------------
-- predictions: one row per user per fixture. Editable until the deadline.
-- points_awarded stays null until the fixture result is settled.
-- ----------------------------------------------------------------------------
create table public.predictions (
  id                    uuid primary key default gen_random_uuid(),
  user_id               uuid not null references public.profiles(id) on delete cascade,
  fixture_id            text not null references public.fixtures(id) on delete cascade,
  predicted_home_score  integer not null check (predicted_home_score >= 0),
  predicted_away_score  integer not null check (predicted_away_score >= 0),
  predicted_potm_player_id text references public.players(id),
  points_awarded        integer,           -- null until settled; then 0..5
  points_breakdown      jsonb,             -- e.g. {"result":3,"potm":2} for transparency
  created_at            timestamptz not null default now(),
  updated_at            timestamptz not null default now(),
  unique (user_id, fixture_id)             -- one prediction per user per fixture
);

create index predictions_user_idx on public.predictions(user_id);
create index predictions_fixture_idx on public.predictions(fixture_id);

-- ----------------------------------------------------------------------------
-- leagues: FPL-style private mini-leagues. Anyone can create one; friends join
-- with the short code. Every player is also on the implicit global leaderboard.
-- ----------------------------------------------------------------------------
create table public.leagues (
  id          uuid primary key default gen_random_uuid(),
  name        text not null,
  code        text not null unique,        -- short join code, e.g. "PL7K2Q"
  created_by  uuid not null references public.profiles(id) on delete cascade,
  created_at  timestamptz not null default now()
);

create table public.league_members (
  league_id uuid not null references public.leagues(id) on delete cascade,
  user_id   uuid not null references public.profiles(id) on delete cascade,
  joined_at timestamptz not null default now(),
  primary key (league_id, user_id)
);

-- ----------------------------------------------------------------------------
-- Auto-create a profile row whenever a new auth user signs up. Supabase fires
-- this trigger on auth.users insert; we read the display_name the app passed in
-- the signup metadata (falling back to the email prefix).
-- ----------------------------------------------------------------------------
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer set search_path = public
as $$
begin
  values (
    new.id,
    coalesce(new.raw_user_meta_data->>'display_name', split_part(new.email, '@', 1))
  );
  return new;
end;
$$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- ============================================================
-- supabase/migrations/0002_scoring.sql
-- ============================================================
-- ============================================================================
-- Scoring engine
-- ============================================================================
-- Points are calculated ONCE per fixture, when the admin settles the result,
-- not on every leaderboard view. That keeps the app fast no matter how many
-- players there are.
--
-- Rules (per fixture, per player):
--   result points:
--     exact score (both numbers match)        -> 3
--     correct outcome only (same W/D/L)        -> 1
--     wrong                                    -> 0
--   POTM points:
--     predicted player == actual POTM          -> 2
--     otherwise                                -> 0
--   total = result + POTM   (0..5)
-- ============================================================================

-- Sign helper: -1 away win, 0 draw, +1 home win.
create or replace function public.match_outcome(home int, away int)
returns int
language sql immutable
as $$ select sign(home - away)::int $$;

-- Settle a single fixture: compute and store points for every prediction on it.
-- Call this after entering home_score, away_score, and potm_player_id.
create or replace function public.settle_fixture(p_fixture_id text)
returns void
language plpgsql
security definer set search_path = public
as $$
declare
  f record;
begin
  select * into f from public.fixtures where id = p_fixture_id;

  if f is null then
    raise exception 'Fixture % not found', p_fixture_id;
  end if;

  if f.home_score is null or f.away_score is null then
    raise exception 'Fixture % has no score yet', p_fixture_id;
  end if;

  update public.predictions p
  set
    points_awarded = result_pts + potm_pts,
    points_breakdown = jsonb_build_object('result', result_pts, 'potm', potm_pts),
    updated_at = now()
  from (
    select
      pr.id,
      -- result points: exact (3) supersedes correct-outcome (1)
      case
        when pr.predicted_home_score = f.home_score
         and pr.predicted_away_score = f.away_score then 3
        when public.match_outcome(pr.predicted_home_score, pr.predicted_away_score)
           = public.match_outcome(f.home_score, f.away_score) then 1
        else 0
      end as result_pts,
      -- POTM points: +2 only if predicted and matches the actual POTM
      case
        when f.potm_player_id is not null
         and pr.predicted_potm_player_id = f.potm_player_id then 2
        else 0
      end as potm_pts
    from public.predictions pr
    where pr.fixture_id = p_fixture_id
  ) calc
  where p.id = calc.id;

  update public.fixtures
    set status = 'finished', result_settled_at = now()
  where id = p_fixture_id;
end;
$$;

-- Undo a settlement: clear the fixture's scores/POTM and wipe the points from
-- every prediction on it. SECURITY DEFINER because an admin cannot edit other
-- players' prediction rows under RLS. Called by the admin "Reset" action.
create or replace function public.unsettle_fixture(p_fixture_id text)
returns void
language plpgsql
security definer set search_path = public
as $$
begin
  if not public.is_admin() then
    raise exception 'Only admins can reset a result';
  end if;

  update public.predictions
    set points_awarded = null, points_breakdown = null, updated_at = now()
  where fixture_id = p_fixture_id;

  update public.fixtures
    set home_score = null, away_score = null, potm_player_id = null,
        status = 'scheduled', result_settled_at = null
  where id = p_fixture_id;
end;
$$;

-- ----------------------------------------------------------------------------
-- Leaderboard: total points per player, ranked. Recomputed live from settled
-- predictions — cheap because it's just a SUM over an indexed column.
-- Exposed as a view so the app can `select * from leaderboard`.
-- ----------------------------------------------------------------------------
-- Left join FROM profiles so every onboarded player appears, even on 0 points
-- (a global leaderboard should list everyone, not only those who have scored).
create or replace view public.leaderboard as
select
  prof.id                                                            as user_id,
  prof.display_name,
  prof.avatar_emoji,
  prof.favourite_team_id,
  coalesce(sum(pr.points_awarded), 0)                                as total_points,
  count(*) filter (where pr.points_breakdown->>'result' = '3')      as exact_scores,
  count(*) filter (where pr.points_awarded is not null)             as settled_predictions,
  rank() over (order by coalesce(sum(pr.points_awarded), 0) desc)   as rank
from public.profiles prof
left join public.predictions pr on pr.user_id = prof.id
where prof.onboarded
group by prof.id, prof.display_name, prof.avatar_emoji, prof.favourite_team_id;

-- The global board is public-by-design: let signed-in users read everyone's totals.
grant select on public.leaderboard to authenticated;

-- Per-league leaderboard: same idea, scoped to members of one league.
-- security definer so it can sum EVERY member's settled points (prediction RLS
-- would otherwise hide other members' rows from the caller).
-- Usage: select * from league_leaderboard(:league_id)
create or replace function public.league_leaderboard(p_league_id uuid)
returns table (
  user_id uuid,
  display_name text,
  avatar_emoji text,
  favourite_team_id text,
  total_points bigint,
  rank bigint
)
language sql stable
security definer set search_path = public
as $$
  select
    lm.user_id,
    prof.display_name,
    prof.avatar_emoji,
    prof.favourite_team_id,
    coalesce(sum(pr.points_awarded), 0) as total_points,
    rank() over (order by coalesce(sum(pr.points_awarded), 0) desc) as rank
  from public.league_members lm
  join public.profiles prof on prof.id = lm.user_id
  left join public.predictions pr on pr.user_id = lm.user_id
  where lm.league_id = p_league_id
  group by lm.user_id, prof.display_name, prof.avatar_emoji, prof.favourite_team_id;
$$;

-- ============================================================
-- supabase/migrations/0003_rls.sql
-- ============================================================
-- ============================================================================
-- Row Level Security (RLS)
-- ============================================================================
-- With RLS on, the database itself enforces who can see/change each row, even
-- if someone talks to it directly with the public API key. Nothing is readable
-- or writable unless a policy below explicitly allows it.
-- ============================================================================

-- Helper: is the current user an admin?
create or replace function public.is_admin()
returns boolean
language sql stable security definer set search_path = public
as $$
  select coalesce((select is_admin from public.profiles where id = auth.uid()), false);
$$;

-- Helper: has the gameweek containing this fixture passed its deadline?
create or replace function public.fixture_deadline_passed(p_fixture_id text)
returns boolean
language sql stable security definer set search_path = public
as $$
  select now() >= gw.deadline
  from public.fixtures f
  join public.gameweeks gw on gw.id = f.gameweek_id
  where f.id = p_fixture_id;
$$;

-- Turn RLS on for every table.
alter table public.profiles       enable row level security;
alter table public.teams          enable row level security;
alter table public.players        enable row level security;
alter table public.gameweeks      enable row level security;
alter table public.fixtures       enable row level security;
alter table public.predictions    enable row level security;
alter table public.leagues        enable row level security;
alter table public.league_members enable row level security;

-- ---- profiles -------------------------------------------------------------
-- Anyone signed in can read profiles (needed to show names on the leaderboard).
create policy "profiles readable by authenticated"
  on public.profiles for select to authenticated using (true);
-- You may only edit your own profile.
create policy "update own profile"
  on public.profiles for update to authenticated
  using (id = auth.uid()) with check (id = auth.uid());
-- You may create your OWN profile row. The signup trigger normally does this,
-- but this lets the app self-heal an account that somehow has no profile row.
create policy "insert own profile"
  on public.profiles for insert to authenticated
  with check (id = auth.uid());
-- ...but only these columns. Column-level grants stop a user from patching
-- their own is_admin flag (self-granting admin). Admin is granted out-of-band
-- via the SQL editor (service role, which bypasses these grants).
revoke update on public.profiles from authenticated;
grant update (display_name, favourite_team_id, avatar_emoji, avatar_url, onboarded, updated_at)
  on public.profiles to authenticated;

-- ---- reference data: teams / players / gameweeks / fixtures ---------------
-- Everyone signed in can read them; only admins can change them.
create policy "teams readable"    on public.teams    for select to authenticated using (true);
create policy "teams admin write" on public.teams    for all    to authenticated using (public.is_admin()) with check (public.is_admin());

create policy "players readable"    on public.players for select to authenticated using (true);
create policy "players admin write" on public.players for all    to authenticated using (public.is_admin()) with check (public.is_admin());

create policy "gameweeks readable"    on public.gameweeks for select to authenticated using (true);
create policy "gameweeks admin write" on public.gameweeks for all    to authenticated using (public.is_admin()) with check (public.is_admin());

create policy "fixtures readable"    on public.fixtures for select to authenticated using (true);
create policy "fixtures admin write" on public.fixtures for all    to authenticated using (public.is_admin()) with check (public.is_admin());

-- ---- predictions ----------------------------------------------------------
-- You can always read your own predictions.
create policy "read own predictions"
  on public.predictions for select to authenticated
  using (user_id = auth.uid());
-- You can read OTHERS' predictions only after that fixture's deadline, so no
-- one can copy before predictions lock.
create policy "read others after deadline"
  on public.predictions for select to authenticated
  using (public.fixture_deadline_passed(fixture_id));
-- You can create your own prediction only before the deadline.
create policy "insert own before deadline"
  on public.predictions for insert to authenticated
  with check (user_id = auth.uid() and not public.fixture_deadline_passed(fixture_id));
-- You can edit your own prediction only before the deadline.
create policy "update own before deadline"
  on public.predictions for update to authenticated
  using (user_id = auth.uid() and not public.fixture_deadline_passed(fixture_id))
  with check (user_id = auth.uid() and not public.fixture_deadline_passed(fixture_id));

-- Helper: is this user a member of this league? SECURITY DEFINER so it reads
-- league_members WITHOUT re-triggering RLS. This is essential — a membership
-- check written directly inside league_members' own SELECT policy would query
-- league_members again and cause infinite RLS recursion in Postgres.
create or replace function public.is_league_member(p_league_id uuid, p_user_id uuid)
returns boolean
language sql stable security definer set search_path = public
as $$
  select exists (
    select 1 from public.league_members
    where league_id = p_league_id and user_id = p_user_id
  );
$$;

-- ---- leagues --------------------------------------------------------------
-- You can read a league if you created it or belong to it.
create policy "read leagues you belong to"
  on public.leagues for select to authenticated
  using (
    created_by = auth.uid()
    or public.is_league_member(id, auth.uid())
  );
-- Anyone signed in can create a league (they become the owner).
create policy "create leagues"
  on public.leagues for insert to authenticated
  with check (created_by = auth.uid());

-- ---- league_members -------------------------------------------------------
-- You can see the member list of leagues you're in (via the definer helper,
-- so this policy does not recurse into league_members).
create policy "read members of my leagues"
  on public.league_members for select to authenticated
  using (public.is_league_member(league_id, auth.uid()));
-- You can add yourself to a league (join). Removing yourself = leave.
create policy "join leagues"
  on public.league_members for insert to authenticated
  with check (user_id = auth.uid());
create policy "leave leagues"
  on public.league_members for delete to authenticated
  using (user_id = auth.uid());

-- ---- league RPCs ----------------------------------------------------------
-- Create a league and auto-join the creator. Generates a unique 6-char code
-- (prefix "PL"). SECURITY DEFINER so the insert + self-membership happen even
-- though the caller cannot yet read the freshly created rows.
create or replace function public.create_league(p_name text)
returns public.leagues
language plpgsql security definer set search_path = public
as $$
declare
  v_uid  uuid := auth.uid();
  v_code text;
  v_row  public.leagues;
begin
  if v_uid is null then
    raise exception 'Not authenticated';
  end if;
  if length(trim(coalesce(p_name, ''))) < 2 then
    raise exception 'League name too short';
  end if;

  -- retry until we land a unique code. Uses built-in random() (no pgcrypto,
  -- which lives in the extensions schema and isn't on our search_path) over an
  -- unambiguous alphabet (no 0/O/1/I).
  loop
    v_code := 'PL';
    for i in 1..4 loop
      v_code := v_code || substr('ABCDEFGHJKLMNPQRSTUVWXYZ23456789',
                                 floor(random() * 32)::int + 1, 1);
    end loop;
    exit when not exists (select 1 from public.leagues where code = v_code);
  end loop;

  values (trim(p_name), v_code, v_uid)
  returning * into v_row;

  values (v_row.id, v_uid);

  return v_row;
end;
$$;

-- Join a league by its invite code. SECURITY DEFINER so a non-member can look
-- the league up by code (the read policy would otherwise hide it) and insert
-- their own membership. Idempotent — re-joining is a no-op.
create or replace function public.join_league_by_code(p_code text)
returns public.leagues
language plpgsql security definer set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_row public.leagues;
begin
  if v_uid is null then
    raise exception 'Not authenticated';
  end if;

  select * into v_row from public.leagues
  where code = upper(trim(p_code));

  if v_row is null then
    raise exception 'No league found for that code';
  end if;

  values (v_row.id, v_uid)
  on conflict (league_id, user_id) do nothing;

  return v_row;
end;
$$;

-- ============================================================
-- supabase/migrations/0004_intro_onboarding.sql
-- ============================================================
-- ============================================================================
-- New-user onboarding manual
-- ============================================================================
-- A short 3-screen "how it works" manual is shown once, right after profile
-- setup (profiles.onboarded) and before a player's first prediction. We track
-- whether a user has seen it with a per-user flag so it never re-appears and so
-- it follows the account across devices (localStorage would re-show on a new
-- browser).
-- ============================================================================

alter table public.profiles
  add column if not exists intro_seen boolean not null default false;

-- Existing players are NOT new users — they should not be interrupted by the
-- manual on their next visit. Mark everyone who already exists as having seen
-- it; only accounts created from here on start with intro_seen = false.
update public.profiles set intro_seen = true;

-- A user finishes the manual by flipping their own intro_seen to true. The
-- column-level UPDATE grant in 0003_rls.sql is an allow-list, so intro_seen has
-- to be added to it explicitly (re-issued here in full to stay in sync).
grant update (display_name, favourite_team_id, avatar_emoji, avatar_url, onboarded, intro_seen, updated_at)
  on public.profiles to authenticated;

-- ============================================================
-- Seed: reference data (teams, squads, current gameweek + fixtures)
-- Generated by scripts/generate-seed-sql.mjs — do not edit by hand.
-- Safe to re-run: upserts on primary key.
-- ============================================================

on conflict (id) do update set name = excluded.name, short_name = excluded.short_name, tla = excluded.tla, color = excluded.color, crest_url = excluded.crest_url;

on conflict (id) do update set team_id = excluded.team_id, name = excluded.name, position = excluded.position;

on conflict (id) do update set number = excluded.number, title = excluded.title, deadline = excluded.deadline, status = excluded.status;

on conflict (id) do update set external_id = excluded.external_id, gameweek_id = excluded.gameweek_id, home_team_id = excluded.home_team_id, away_team_id = excluded.away_team_id, kickoff_time = excluded.kickoff_time;

-- ---------------------------------------------------------------------------
-- ONE-TIME ADMIN BOOTSTRAP: after you sign up in the app, run ONE of these
-- (while signed in as yourself) to unlock the admin panel:
--   update public.profiles set is_admin = true where id = auth.uid();
--   update public.profiles set is_admin = true where display_name = 'YOUR NAME';
-- ---------------------------------------------------------------------------
